//! 🏭️ Batched original numeric decisions publish genuine sparse rows, exact messages and executable inverse events.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_diff::LayoutDiff;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_os_kernel::{RetainedFieldPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext,MutationMessage,MutationMessageLedgerRetirement};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,ErasedSnapshotRetirement,retained_clone::{RetainedCloneRef,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_factory::vector::FactoryVectorRetirement;
use super::{batch_plan::FrameSelectionPlan,batch_output::BatchOutput,batch_inverse::BatchInverse,batch_message::DynamicMessagePreparation,batch_source::{BatchDiagnosticSource,count}};
use std::mem::{ManuallyDrop,size_of};
pub fn selected(m:&LayoutMutation)->bool{matches!(m,LayoutMutation::DragFrames(_)|LayoutMutation::RotateFrames(_)|LayoutMutation::ScaleFrames(_))}
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"batch mutation original preparation custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<LayoutMutation>()*3+size_of::<LayoutDiff>()*3+size_of::<MutationMessage>()*3+512,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=fixed().copy_bytes;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed().copy_bytes,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=fixed().copy_bytes;p.copied_items=p.copied_items.max(1);p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
/// 🧳 Original plan authority outlives every partial diagnostic, payload, output and inverse owner.
pub struct BatchPreparation{plan:FrameSelectionPlan,payload:RetainedFieldPreparation<LayoutMutation>,output:BatchOutput,inverse:BatchInverse,diagnostic:DynamicMessagePreparation,messages:ManuallyDrop<Option<Vec<MutationMessage>>>,scratch_ledger:ManuallyDrop<Option<MutationMessageLedgerRetirement>>,payload_rows:ManuallyDrop<Option<Vec<LayoutMutation>>>,inverse_rows:ManuallyDrop<Option<Vec<LayoutMutation>>>,mutation_retirement:Option<FactoryVectorRetirement<LayoutMutation>>,diff:ManuallyDrop<Option<LayoutDiff>>,retirement:RetainedCloneClose,ledger:ManuallyDrop<Option<MutationMessageLedgerRetirement>>,phase:u8,index:usize,inverse_phase:u8,decision_ready:bool,inverse_ready:bool,closing:bool}
impl Default for BatchPreparation{fn default()->Self{Self{plan:Default::default(),payload:Default::default(),output:Default::default(),inverse:Default::default(),diagnostic:Default::default(),messages:ManuallyDrop::new(None),scratch_ledger:ManuallyDrop::new(None),payload_rows:ManuallyDrop::new(None),inverse_rows:ManuallyDrop::new(None),mutation_retirement:None,diff:ManuallyDrop::new(None),retirement:Default::default(),ledger:ManuallyDrop::new(None),phase:0,index:0,inverse_phase:0,decision_ready:false,inverse_ready:false,closing:false}}}
impl BatchPreparation{
 pub fn decision_demand(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.decision_ready{return Err(fault())}if self.phase>0{self.plan.verify(m,b)?}Ok(match self.phase{0=>nested(self.plan.demand(m,b)?),1=>RetirementDemand{capacity_bytes:count(&self.plan)*size_of::<MutationMessage>(),..fixed()},2=>if self.index==count(&self.plan){fixed()}else{nested(self.diagnostic.demand(&BatchDiagnosticSource{m,b,plan:&self.plan,index:self.index},body.min(256))?)},3=>nested(self.diagnostic.take_demand()),4=>if !self.diagnostic.terminal_is_empty(){nested(self.diagnostic.close_demand(body.min(256))?)}else if let Some(ledger)=self.scratch_ledger.as_ref(){nested(ledger.next_demand(body.min(256))?)}else{fixed()},5=>if self.payload.value().is_some(){fixed()}else{nested(self.payload.demand(m,body.min(256))?)},6=>RetirementDemand{capacity_bytes:size_of::<LayoutMutation>(),..fixed()},7=>nested(self.payload.exchange_demand()?),8=>nested(self.output.demand(&self.plan,m,b)?),9=>nested(self.output.take_demand()),90=>fixed(),_=>return Err(fault())})}
 pub fn decide(&mut self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.decision_demand(m,b,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedMutationAdvance::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{
 0=>{let step=self.plan.advance(m,b,child(g)).map_err(refused)?;p=receipt(step.progress());if self.plan.ready(){self.phase=1}},
 1=>{self.phase=254;*self.messages=Some(Vec::new());let rows=self.messages.as_mut().unwrap();let reserved=rows.try_reserve_exact(count(&self.plan));p.retained_capacity_bytes=rows.capacity()*size_of::<MutationMessage>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=2},
 2=>if self.index==count(&self.plan){if self.plan.failure.is_some()||self.plan.changed().is_empty(){*self.diff=Some(LayoutDiff::default());self.phase=90}else{self.phase=5}}else{let step=self.diagnostic.advance(&BatchDiagnosticSource{m,b,plan:&self.plan,index:self.index},body.min(256),child(g)).map_err(refused)?;p=receipt(step.progress());if self.diagnostic.ready(){self.phase=3}},
 3=>{let(mut rows,paid)=self.diagnostic.take(child(g)).map_err(refused)?.ok_or_else(fault)?;p=receipt(paid);let row=rows.pop().ok_or_else(fault)?;self.messages.as_mut().ok_or_else(fault)?.push(row);*self.scratch_ledger=Some(MutationMessageLedgerRetirement::new(String::new(),rows));self.diagnostic.begin_close();self.phase=4},
 4=>if !self.diagnostic.terminal_is_empty(){p=receipt(self.diagnostic.close_step(child(g)).map_err(refused)?.progress())}else if let Some(ledger)=self.scratch_ledger.as_mut(){if ledger.terminal_is_empty(){*self.scratch_ledger=None}else{p=receipt(ledger.close_step(child(g)).map_err(refused)?.progress())}}else{self.diagnostic=Default::default();self.index+=1;self.phase=2},
 5=>if self.payload.value().is_some(){self.phase=6}else{p=receipt(self.payload.advance(m,body.min(256),child(g)).map_err(refused)?.progress())},
 6=>{self.phase=254;*self.payload_rows=Some(Vec::new());let rows=self.payload_rows.as_mut().unwrap();let reserved=rows.try_reserve_exact(1);p.retained_capacity_bytes=rows.capacity()*size_of::<LayoutMutation>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=7},
 7=>{let(value,paid)=self.payload.take(child(g)).map_err(refused)?;p=receipt(paid);self.payload_rows.as_mut().ok_or_else(fault)?.push(value.ok_or_else(fault)?);self.phase=8},
 8=>{let step=self.output.advance(self.payload_rows.as_mut().ok_or_else(fault)?,&self.plan,m,b,child(g)).map_err(refused)?;p=receipt(step.progress());if matches!(step,RetainedCloneStep::Complete(_)){self.phase=9}},
 9=>{let(value,paid)=self.output.take(child(g)).map_err(refused)?;p=receipt(paid);*self.diff=value;self.phase=90},90=>{self.decision_ready=true;return Ok(RetainedMutationAdvance::Ready(p))},_=>return Err(fault())}Ok(RetainedMutationAdvance::Progress(p))}
 pub fn take_decision(&mut self)->RetainedMutationDecision<LayoutDiff>{assert!(self.decision_ready&&!self.closing);let rows=self.messages.take().unwrap_or_default();if self.plan.failure.is_some(){RetainedMutationDecision::Refused(rows)}else{RetainedMutationDecision::Admitted(self.diff.take().expect("original sparse batch output"),rows)}}
 pub fn inverse_demand(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||!self.decision_ready||self.plan.failure.is_some()||self.inverse_ready{return Err(fault())}self.plan.verify(m,b)?;Ok(if self.inverse_phase==0{nested(self.inverse.demand(&self.plan,m,b,body.min(256))?)}else{nested(self.inverse.take_demand())})}
 pub fn inverse(&mut self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.inverse_demand(m,b,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedMutationAdvance::Progress(Default::default()))}if self.inverse_phase==0{let step=self.inverse.advance(&self.plan,m,b,body.min(256),child(g)).map_err(refused)?;let p=receipt(step.progress());if matches!(step,RetainedCloneStep::Complete(_)){self.inverse_phase=1}Ok(RetainedMutationAdvance::Progress(p))}else{let(rows,p)=self.inverse.take(child(g)).map_err(refused)?;*self.inverse_rows=rows;self.inverse_ready=true;Ok(RetainedMutationAdvance::Ready(receipt(p)))}}
 pub fn take_inverse(&mut self)->Vec<LayoutMutation>{assert!(self.inverse_ready&&!self.closing);self.inverse_rows.take().unwrap_or_default()}
 pub fn begin_close(&mut self){self.closing=true;self.inverse.begin_close();self.output.begin_close();self.payload.begin_close();self.diagnostic.begin_close();self.plan.begin_close()}
 pub fn close_demand(&self,c:RetainedMutationCloseContext<'_,LayoutMutation>,body:usize)->Result<RetirementDemand,ValueError>{if !self.inverse.terminal_is_empty(){return self.inverse.close_demand(c,body)}if !self.output.terminal_is_empty(){return self.output.close_demand(body)}if !self.payload.terminal_is_empty(){return self.payload.close_demand(body)}if !self.diagnostic.terminal_is_empty(){return self.diagnostic.close_demand(body)}if let Some(ledger)=self.scratch_ledger.as_ref(){return ledger.next_demand(body)}if !self.plan.terminal_is_empty(){return self.plan.close_demand(body)}if !self.retirement.is_empty()||self.diff.is_some(){return self.retirement.next_owner_demands::<LayoutDiff>(self.diff.is_some(),&None,body)}if let Some(owner)=self.mutation_retirement.as_ref(){return if owner.terminal_is_empty(){Ok(fixed())}else{owner.demands(c.mutations,body)}}if self.payload_rows.is_some()||self.inverse_rows.is_some(){return Ok(FactoryVectorRetirement::<LayoutMutation>::constructor_demand())}if self.messages.is_some(){return Ok(fixed())}if let Some(ledger)=self.ledger.as_ref(){return ledger.next_demand(body)}Ok(fixed())}
 pub fn close_step(&mut self,c:RetainedMutationCloseContext<'_,LayoutMutation>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(c,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.inverse.terminal_is_empty(){return self.inverse.close_step(c,g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.output.terminal_is_empty(){return self.output.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.payload.terminal_is_empty(){return self.payload.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.diagnostic.terminal_is_empty(){return self.diagnostic.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(ledger)=self.scratch_ledger.as_mut(){if ledger.terminal_is_empty(){*self.scratch_ledger=None}else{return ledger.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if !self.plan.terminal_is_empty(){return self.plan.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(step)=self.retirement.begin_granted(&mut self.diff,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))}if let Some(owner)=self.mutation_retirement.as_mut(){if owner.terminal_is_empty(){self.mutation_retirement=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}return owner.close_step(c.mutations,g).map(|s|RetainedCloneStep::Progress(s.progress()))}let payload=self.payload_rows.is_some();let rows=if payload{self.payload_rows.take()}else{self.inverse_rows.take()};if let Some(rows)=rows{match FactoryVectorRetirement::admit(rows,g){Ok((owner,p))=>{self.mutation_retirement=Some(owner);return Ok(RetainedCloneStep::Progress(p))},Err((error,rows))=>{if payload{*self.payload_rows=Some(rows)}else{*self.inverse_rows=Some(rows)}return Err(error)}}}if let Some(rows)=self.messages.take(){*self.ledger=Some(MutationMessageLedgerRetirement::new(String::new(),rows));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if let Some(ledger)=self.ledger.as_mut(){if ledger.terminal_is_empty(){*self.ledger=None}else{return ledger.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.inverse.terminal_is_empty()&&self.output.terminal_is_empty()&&self.payload.terminal_is_empty()&&self.diagnostic.terminal_is_empty()&&self.plan.terminal_is_empty()&&self.scratch_ledger.is_none()&&self.diff.is_none()&&self.retirement.is_empty()&&self.payload_rows.is_none()&&self.inverse_rows.is_none()&&self.mutation_retirement.is_none()&&self.messages.is_none()&&self.ledger.is_none()}
}
impl Drop for BatchPreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"batch preparation needs original funded cleanup")}}
